#include <stdio.h>
/* ex08：VLAN 标签的代价——4 字节开销意味着什么
 * IEEE 802.1Q 在源 MAC 之后插入 4 字节 Tag（TPID 0x8100 + TCI）。
 * 后果：
 *   ① 帧变长 -> 同样带宽能传的有效载荷变少；
 *   ② MTU 不变（1500）时，Tag 会让帧超过 1518 -> 部分设备会丢「超长帧」；
 *   ③ 小包场景下开销占比很高，是「小包性能」话题的一部分。
 * 本程序量化这三种影响。*/
int main(void) {
    int payloads[] = {64, 128, 512, 1024, 1460};
    const char *note[] = {"64B(min)", "", "", "", "1460B(full MTU)"};

    printf("以太网帧开销：前导码8B + 帧头14B + FCS4B + 帧间隙12B，VLAN 另加 4B\n");
    printf("------------------------------------------------------------------\n");
    printf("%-8s %-12s %-12s %-11s %-9s %s\n", "payload", "frame(B)", "tagged(B)", "overhead", ">1518?", "备注");

    for (int i = 0; i < 5; i++) {
        int base = payloads[i] + 14 + 4;          /* 帧头 + FCS（不含前导码） */
        int tagged = base + 4;
        double overhead = 4.0 / tagged * 100.0;
        printf("%-8d %-12d %-12d %10.2f%% %-9s %s\n", payloads[i], base, tagged, overhead,
               tagged > 1518 ? "是" : "否", note[i]);
    }
    printf("------------------------------------------------------------------\n");
    printf("换算成带宽：1Gbps 链路上，64B 小包（含 Tag）的线速包率为\n");
    {
        int tagged = 64 + 14 + 4 + 4;             /* 86B */
        int wire = tagged + 8 + 12;               /* 加前导码 8B 与帧间隙 12B = 106B */
        double pps = 1e9 / (wire * 8);
        int wire_plain = 64 + 14 + 4 + 8 + 12;    /* 无 Tag 时 102B */
        double pps_plain = 1e9 / (wire_plain * 8);
        printf("  有 Tag：%d 字节/包（含前导码与间隙）-> %.1f kpps -> 有效吞吐 %.1f Mbps\n",
               wire, pps / 1000.0, pps * 64 * 8 / 1e6);
        printf("  无 Tag：%d 字节/包（含前导码与间隙）-> %.1f kpps -> 有效吞吐 %.1f Mbps\n",
               wire_plain, pps_plain / 1000.0, pps_plain * 64 * 8 / 1e6);
        printf("  -> 小包场景下 4 字节 Tag 让线速包率下降 %.2f%%，有效吞吐下降 %.2f%%\n",
               (pps_plain - pps) / pps_plain * 100.0,
               (pps_plain - pps) / pps_plain * 100.0);
    }
    printf("\n结论：4 字节 Tag 对满 MTU 大包只占 %.2f%%（几乎无感），\n", 4.0 / (1460 + 14 + 4 + 4) * 100);
    printf("      但对 64B 小包意味着接近 4%% 的线速损失 ——\n");
    printf("      高频交易/游戏服务器/小包转发网关会实打实地在意这个数字。\n");
    return 0;
}
